 $imap->append('INBOX',$tinyRaw,'\\Seen');$tinyRows=$imap->messages('INBOX',1,50,'Tiny transfer encoding');check($tinyRows['total']>0,'Tiny encoded attachment test message appended');
 $tinyUid=(int)$tinyRows['messages'][0]['uid'];$smallLimitImap=new NativeImapClient($host,$imapPort,'none',$user,$pass,8);
