 $imap->setFlag('INBOX',$uid,'flagged',true);$imap->move('INBOX',$uid,'Milestone2Integration');$moved=$imap->messages('Milestone2Integration',1,25);check($moved['total']>0,'IMAP message moved to custom folder');
 $movedUid=(int)$moved['messages'][0]['uid'];$imap->delete('Milestone2Integration',$movedUid);check($imap->messages('Milestone2Integration',1,25)['total']===0,'IMAP message deleted and expunged');
 $draftSubject='Editable draft '.bin2hex(random_bytes(3));$draftPayload=['from'=>$email,'to'=>'','cc'=>'','bcc'=>$email,'subject'=>$draftSubject,'body'=>'Draft persisted on IMAP','attachments'=>[['name'=>'draft.txt','path'=>$tmp,'type'=>'text/plain']]];
 $webmail->saveDraft(['email'=>$email,'password'=>$pass],$draftPayload);$drafts=$imap->messages('Drafts',1,25,$draftSubject);check($drafts['total']>0,'Draft saved to the real IMAP Drafts folder');
 $draftUid=(int)$drafts['messages'][0]['uid'];$draftRead=$imap->message('Drafts',$draftUid);check($draftRead['bcc']===$email,'Draft-only BCC metadata is retained without exposing it on sent messages');$extraDraftFiles=array_fill(0,5,['name'=>'extra.txt','type'=>'text/plain','data'=>'extra']);try{$webmail->replaceDraft(['email'=>$email,'password'=>$pass],'Drafts',$draftUid,['from'=>$email,'subject'=>$draftSubject,'body'=>'This edit must be rejected','attachments'=>$extraDraftFiles]);throw new RuntimeException('Expected combined attachment-count rejection');}catch(InvalidArgumentException $e){check(str_contains($e->getMessage(),'five attachments'),'Draft edit rejects more than five combined attachments');}check($imap->messages('Drafts',1,25,$draftSubject)['total']>0,'Rejected over-limit edit leaves the original draft intact');$limitedConfig=new Config(['MAIL_IMAP_HOST'=>$host,'MAIL_IMAP_PORT'=>(string)$imapPort,'MAIL_IMAP_ENCRYPTION'=>'none','MAIL_FOLDER_DRAFTS'=>'Drafts','MAIL_ATTACHMENT_MAX_BYTES'=>'10485760','MAIL_ATTACHMENT_TOTAL_MAX_BYTES'=>'100']);$limitedWebmail=new MailboxWebmailService(new MailTransportFactory($limitedConfig),$limitedConfig,$mime);try{$limitedWebmail->replaceDraft(['email'=>$email,'password'=>$pass],'Drafts',$draftUid,['from'=>$email,'subject'=>$draftSubject,'body'=>'This edit exceeds the combined byte limit','attachments'=>[['name'=>'large.txt','type'=>'text/plain','data'=>str_repeat('x',90)]]]);throw new RuntimeException('Expected combined attachment-size rejection');}catch(InvalidArgumentException $e){check(str_contains($e->getMessage(),'Combined draft attachments'),'Draft edit enforces combined attachment byte limit');}check($imap->messages('Drafts',1,25,$draftSubject)['total']>0,'Rejected over-limit size edit leaves the original draft intact');$webmail->replaceDraft(['email'=>$email,'password'=>$pass],'Drafts',$draftUid,['from'=>$email,'to'=>'','cc'=>'','bcc'=>$draftRead['bcc'],'subject'=>$draftSubject.' updated','body'=>'Updated draft']);$updated=$imap->messages('Drafts',1,25,$draftSubject.' updated');check($updated['total']>0,'Existing IMAP draft updated without losing draft state');
 $updatedUid=(int)$updated['messages'][0]['uid'];$updatedMessage=$imap->message('Drafts',$updatedUid);check(count($updatedMessage['attachments'])===1,'Edited draft retained its original attachment');$retained=$imap->downloadPart('Drafts',$updatedUid,$updatedMessage['attachments'][0]['part']);check(str_contains($retained['data'],'real attachment test'),'Edited draft attachment bytes remain intact');
 $draftSendResult=$webmail->sendDraft(['email'=>$email,'password'=>$pass],'Drafts',$updatedUid,['from'=>$email,'to'=>$email,'cc'=>'','bcc'=>'','subject'=>'Sent from draft '.bin2hex(random_bytes(3)),'body'=>'Draft sent through SMTP','bcc'=>$updatedMessage['bcc']]);check($draftSendResult['sent_copy_saved']&&$draftSendResult['draft_removed'],'Sent draft copied to Sent and removed from Drafts');check($imap->messages('Drafts',1,25,$draftSubject.' updated')['total']===0,'Sent draft no longer appears in Drafts');$sentRows=$imap->messages('Sent Items',1,25,'Sent from draft');$sentUid=(int)$sentRows['messages'][0]['uid'];$sentRead=$imap->message('Sent Items',$sentUid);check(($sentRead['bcc']??'')==='','Sent message does not expose BCC in stored headers');check(count($sentRead['attachments'])===1,'Sent draft retains its attachment after SMTP delivery');$sentAttachment=$imap->downloadPart('Sent Items',$sentUid,$sentRead['attachments'][0]['part']);check(str_contains($sentAttachment['data'],'real attachment test'),'Sent draft attachment bytes are delivered intact');
 unlink($tmp);
}finally{$imap->close();}
echo "IMAP/SMTP integration suite passed.\n";
